from decimal import Decimal


def parse_miles(text):
    match = re.fullmatch(
        r"\s*(\d{1,3}(?:,\d{3})+|\d+)(\.\d+)?\s*(k)?\s*(?:miles?|mi)?\s*",
        text,
        re.IGNORECASE,
    )
    if not match:
        raise ValueError(f"Invalid mileage: {text!r}")

    number = Decimal(match.group(1).replace(",", "") + (match.group(2) or ""))
    return int(number * (1000 if match.group(3) else 1))

